const flightBaseTranslate=translateDynamic;
translateDynamic=function(text){
 if(settings.language==='ko')return text;const exact=tr(text);if(exact!==text)return exact;
 const n={en:0,ja:1,zh:2}[settings.language],p=words=>words[n];let m;
 if((m=text.match(/^([★☆] )(.+)$/)))return m[1]+translateDynamic(m[2]);
 if((m=text.match(/^(\d+(?:\.\d+)?)초 안에 완주$/)))return p(['Finish within '+m[1]+' s',m[1]+'秒以内に完走',m[1]+'秒内完成']);
 if((m=text.match(/^코인 (\d+)개 (이상 |모두 )?모아 완주$/)))return p(['Finish with '+(m[2]==='이상 '?'at least ':'')+m[1]+' coins','コイン'+m[1]+'個'+(m[2]==='이상 '?'以上':'')+'を集めて完走','收集'+(m[2]==='이상 '?'至少':'')+m[1]+'枚金币并通关']);
 if((m=text.match(/^시작 연료 (\d+(?:\.\d+)?)% · (.+)$/)))return p(['Starting fuel ','開始燃料 ','起始燃料 '])+m[1]+'% · '+translateDynamic(m[2]);
 if((m=text.match(/^(.+) · 적용 중: (.*) \/ (\d+)줄$/)))return translateDynamic(m[1])+p([' · Active map: ',' · 適用中: ',' · 当前地图：'])+m[2]+' / '+m[3]+p([' rows','行','行']);
 if((m=text.match(/^(.+) · 수정 맵$/)))return translateDynamic(m[1])+p([' · Edited map',' · 編集マップ',' · 修改地图']);
 if((m=text.match(/^최고 (\d+\.\d+)초 · ([★☆]+)$/)))return p(['Best ','ベスト ','最佳 '])+m[1]+' s · '+m[2];
 if((m=text.match(/^첫 완주 ◈ (\d+) · 추가 단계 ◈ 40$/)))return p(['First finish ◈ ','初完走 ◈ ','首次通关 ◈ '])+m[1]+p([' · Each new tier ◈ 40',' · 追加段階 ◈ 40',' · 每个新阶段 ◈ 40']);
 if((m=text.match(/^첫 완주 ◈ (\d+) · 2·3단계 각각 ◈ 40(?: · 보상 획득 완료)?$/)))return p(['First finish ◈ ','初完走 ◈ ','首次通关 ◈ '])+m[1]+p([' · Tiers 2/3: ◈ 40 each',' · 2・3段階は各◈ 40',' · 第2/3阶段各◈ 40'])+(text.endsWith('보상 획득 완료')?' · '+tr('보상 획득 완료'):'');
 if((m=text.match(/^보유 코인 ◈ (\d+) · 장착 기체 (.+)$/)))return tr('보유 코인')+' ◈ '+m[1]+p([' · Equipped: ',' · 装備機体 ',' · 已装备 '])+tr(m[2]);
 if((m=text.match(/^다음 ★(\d+) · (.+)$/)))return p(['Next ','次の報酬 ','下个奖励 '])+'★'+m[1]+' · '+tr(m[2]);
 if((m=text.match(/^(\d+\.\d+)초 · 남은 연료 (\d+)% · 수집 (\d+)개$/)))return m[1]+p([' s · Fuel ','秒 · 残燃料 ','秒 · 剩余燃料 '])+m[2]+'%'+p([' · Coins ',' · コイン ',' · 金币 '])+m[3];
 if((m=text.match(/^(.+) · 도달 (\d+) m$/)))return translateDynamic(m[1])+p([' · Distance ',' · 到達 ',' · 到达 '])+m[2]+' m';
 if((m=text.match(/^획득 코인 ◈ (\d+)(.*)$/)))return tr('획득 코인')+' ◈ '+m[1]+translateDynamic(m[2]);
 if((m=text.match(/^(.*) · 보상 해금: (.+)$/)))return translateDynamic(m[1])+p([' · Unlocked: ',' · 報酬解放: ',' · 解锁奖励：'])+m[2].split(' / ').map(tr).join(' / ');
 if(text===' · 신규 목표 보상 포함')return p([' · Includes new-goal rewards',' · 新目標報酬を含む',' · 含新目标奖励']);
 if(text===' · 달성 보상은 최초 1회 지급')return p([' · Goal rewards are paid once',' · 達成報酬は初回のみ',' · 目标奖励仅发放一次']);
 if((m=text.match(/^(TIME ATTACK|FUEL SURVIVAL|PRECISION FLIGHT) · (.+)$/)))return m[1]+' · '+translateDynamic(m[2]);
 if((m=text.match(/^목표 속도 ([0-9.]+) km\/h$/)))return p(['Target speed ','目標速度 ','目标速度 '])+m[1]+' km/h';
 if((m=text.match(/^남은 시간 (\d+\.\d+)초$/)))return p(['Time left ','残り時間 ','剩余时间 '])+m[1]+' s';
 if((m=text.match(/^경과 (\d+\.\d+)초 · 연료 (\d+)%$/)))return p(['Elapsed ','経過 ','已用 '])+m[1]+p([' s · Fuel ','秒 · 燃料 ','秒 · 燃料 '])+m[2]+'%';
 if((m=text.match(/^코인 (\d+) \/ (\d+)$/)))return p(['Coins ','コイン ','金币 '])+m[1]+' / '+m[2];
 return flightBaseTranslate(text);
};
